ge selection"}, {"id": "224820b6-7127-4776-ac84-984dcead64ea", "type": "concept", "title": "Enhancements"}, {"id": "5e44fdc1-1bfa-4fb4-b502-44f85d931aef", "type": "concept", "title": "Declination and diversion"}], "description": "Charging is one of the most consequential discretionary decisions in the criminal process."}, {"id": "6f7a7d7a-97e5-44d8-90d3-3f84b110c77f", "type": "subtopic", "title": "Ethics and minister of justice role", "children": [{"id": "334252bd-a1e9-4c01-9bc5-489b6319948b", "type": "concept", "title": "Brady obligations"}, {"id": "8ed103c4-75f6-4b70-9d83-f9e55462c87d", "type": "concept", "title": "Discovery ethics"}, {"id": "f12946c7-45d2-4675-a86b-8a8702c17efe", "type": "concept", "title": "Victim consultation"}, {"id": "ca60a35a-2594-4e1b-bab1-fbf75f4276e6", "type": "concept", "title": "Avoiding improper pressure"}], "description": "Prosecutors are advocates but also public officials with special duties to fairness and truth."}, {"id": "0d7d321e-b469-4b5f-a2fd-d2906ec05305", "type": "subtopic", "title": "Discretion and accountability", "children": [{"id": "36d4d76c-8406-4e1b-a2ea-7111dd2f20af", "type": "concept", "title": "Office policies"}, {"id": "c015d5d4-5919-4155-9aa5-1afc91133bdc", "type": "concept", "title": "Data transparency"}, {"id": "47d84ed0-68a1-4e0a-aef4-abe74aa6da33", "type": "concept", "title": "Elected prosecutors"}, {"id": "ff997ef4-591d-4c67-bda7-456921ed9dbc", "type": "concept", "title": "Racial and geographic disparities"}], "description": "Students assess how prosecutorial power is reviewed, measured, and constrained."}]}, {"id": "b0eae564-2a35-4630-becc-dd67e78436d2", "type": "topic", "title": "Defense Counsel, Indigent Defense, and Effective Assistance", "description": "Examine the constitutional, ethical, and practical role of defense counsel, including public defense systems.", "children": [{"id": "c1f9d18d-fd2a-4c0e-bc8d-a8d9ea3994d8", "type": "subtopic", "title": "Right to counsel", "children": [{"id": "fe5f22d0-3c6a