update public.learning_paths
set
  title = 'Courts and Adjudication',
  goal = 'Courts and Adjudication',
  summary = 'Map how American adjudication is divided across federal, state, trial, appellate, criminal, civil, and specialized court systems. Topics cover rule of law, due process, and adjudicative values; court actors and institutional roles; prosecutorial discretion and charging; defense counsel, indigent defense, and effective assistance; pretrial process; plea bargaining, diversion, and case disposition; evidence, discovery, and case preparation; trial process and adversarial procedure; jury selection, deliberation, and verdicts; sentencing law, guidelines, and punishment purposes; appeals, post-conviction review, and habeas; specialized and problem-solving courts; court administration, caseflow, and judicial performance; technology, data, and access to justice; inequality, disparities, and legitimacy in courts; victims, witnesses, and community participation; and court observation, policy reform, and capstone analysis.',
  data = $ctadjson${"slug": "courts-and-adjudication", "title": "Courts and Adjudication", "description": "Map how American adjudication is divided across federal, state, trial, appellate, criminal, civil, and specialized court systems. Topics cover rule of law, due process, and adjudicative values; court actors and institutional roles; prosecutorial discretion and charging; defense counsel, indigent defense, and effective assistance; pretrial process; plea bargaining, diversion, and case disposition; evidence, discovery, and case preparation; trial process and adversarial procedure; jury selection, deliberation, and verdicts; sentencing law, guidelines, and punishment purposes; appeals, post-conviction review, and habeas; specialized and problem-solving courts; court administration, caseflow, and judicial performance; technology, data, and access to justice; inequality, disparities, and legitimacy in courts; victims, witnesses, and community participation; and court observation, policy reform, and capstone analysis.", "topics": [{"id": "bd36ce5d-84bb-44ce-8aff-63c29c40acdc", "type": "topic", "title": "American Court Systems and Jurisdiction", "description": "Map how American adjudication is divided across federal, state, trial, appellate, criminal, civil, and specialized court systems.", "children": [{"id": "9ecb8541-f85e-4ac5-b73e-c6ff6510ef84", "type": "subtopic", "title": "Federal and state court structure", "children": [{"id": "e1e596ce-95e9-4151-817a-bbb31317d72f", "type": "concept", "title": "Trial and appellate courts"}, {"id": "773cd19e-37fe-4675-9d92-81375907de91", "type": "concept", "title": "Supreme courts"}, {"id": "5c07ac4d-bea7-4f8a-983e-269c88f1df3b", "type": "concept", "title": "Limited and general jurisdiction"}, {"id": "26f5436b-cdce-4313-9bbf-39335a945727", "type": "concept", "title": "Federalism and state variation"}], "description": "Students need the institutional map before they can understand who decides what and why."}, {"id": "0f52dbfb-8877-4b1e-9898-ee9f1ae1c7df", "type": "subtopic", "title": "Subject-matter and territorial authority", "children": [{"id": "0bd921d5-9766-486b-b155-3e9552938ad5", "type": "concept", "title": "Subject-matter jurisdiction"}, {"id": "8d6b67d6-8e99-4f73-842e-494a308c1e2f", "type": "concept", "title": "Personal jurisdiction overview"}, {"id": "57077ba0-3133-41d1-84bd-d787e2e356fa", "type": "concept", "title": "Venue"}, {"id": "58e08d41-1c99-445c-bccb-bf171fd270f9", "type": "concept", "title": "Removal and transfer awareness"}], "description": "Jurisdiction determines whether a court has legal power to hear a case."}, {"id": "869875c5-5cd2-4528-84fa-a46f62768dcc", "type": "subtopic", "title": "Criminal, civil, and administrative adjudication", "children": [{"id": "d9b81807-0456-4382-a4e1-354b1f4fe076", "type": "concept", "title": "Criminal courts"}, {"id": "24d41f04-69bf-467d-b761-e8d72ffb226a", "type": "concept", "title": "Civil courts"}, {"id": "0979a67e-bb2f-4778-9e01-a142259f9f4c", "type": "concept", "title": "Administrative hearings"}, {"id": "fd804605-b3bd-4aaa-b653-36afb51d13fb", "type": "concept", "title": "Judicial review"}], "description": "Adjudication is broader than criminal trial; courts interact with civil disputes and agency decisions."}]}, {"id": "90171bbe-ffd6-4a54-9b5e-b231c1cc6213", "type": "topic", "title": "Rule of Law, Due Process, and Adjudicative Values", "description": "Understand courts as institutions for lawful, fair, public, and reasoned dispute resolution.", "children": [{"id": "0ab06449-51ec-4b74-bd52-b377412cff93", "type": "subtopic", "title": "Rule of law", "children": [{"id": "0c02e994-06cc-4c92-a313-c1d4ea03f362", "type": "concept", "title": "Legality"}, {"id": "b7725a95-6c6e-4b04-b5f2-cd9503ecadbd", "type": "concept", "title": "Neutrality"}, {"id": "8e1d18a2-f572-49e3-bd38-e1a7a60c2832", "type": "concept", "title": "Public proceedings"}, {"id": "8e7d9093-22fd-45cd-988d-6a8dc4f9d258", "type": "concept", "title": "Reasoned judgments"}], "description": "The rule of law frames courts as institutions that constrain power through public rules and reasoned decisions."}, {"id": "ccbe0ceb-e3b7-4b83-ac82-bf06050338a3", "type": "subtopic", "title": "Procedural due process", "children": [{"id": "845ea884-3d67-4887-aeea-80c8da4bc81e", "type": "concept", "title": "Notice"}, {"id": "3e05edf6-f8e5-4f31-8c41-2573b50e4896", "type": "concept", "title": "Opportunity to be heard"}, {"id": "cbc54304-2090-4816-ada3-3c836aa32899", "type": "concept", "title": "Impartial decision-maker"}, {"id": "0ee7c679-1ede-4d1b-bac5-60fc16f0ccd4", "type": "concept", "title": "Accuracy and fairness"}], "description": "Due process asks what procedures are required before the state deprives liberty, property, or life."}, {"id": "a70c777e-e3a6-4ba5-a514-d7bcee371819", "type": "subtopic", "title": "Competing system values", "children": [{"id": "329d23f7-d1ac-474c-b9fb-9d836fc0d595", "type": "concept", "title": "Accuracy"}, {"id": "249bb46d-3238-4a72-8d64-77f860058699", "type": "concept", "title": "Efficiency"}, {"id": "b5aee4a8-9358-4ce6-83ec-917fc59feb87", "type": "concept", "title": "Finality"}, {"id": "2bbece57-ea67-4718-8841-097377f457ce", "type": "concept", "title": "Legitimacy"}], "description": "Courts must balance fairness, efficiency, dignity, finality, transparency, and public safety."}]}, {"id": "255a8efb-d7af-4cc2-b25a-18667bf5037d", "type": "topic", "title": "Court Actors and Institutional Roles", "description": "Study how judges, prosecutors, defense attorneys, clerks, court staff, probation, victims, witnesses, and juries shape adjudication.", "children": [{"id": "2d61ca0b-c900-4ec4-9111-3640bf42095f", "type": "subtopic", "title": "Judges and judicial behavior", "children": [{"id": "0d6adb68-8ab9-4146-9bb2-b01a2591d783", "type": "concept", "title": "Trial judges"}, {"id": "afb337b6-e4d6-4472-9e87-e549cff75525", "type": "concept", "title": "Appellate judges"}, {"id": "477bacc9-8373-4ea1-8409-da34146bba20", "type": "concept", "title": "Judicial discretion"}, {"id": "4bf0da83-e7a1-4a83-bdc8-8f4f7b6835d8", "type": "concept", "title": "Judicial ethics"}], "description": "Judges manage proceedings, interpret law, sentence defendants, and signal institutional norms."}, {"id": "43a82ffb-246d-4c74-a98d-fcacd29d1649", "type": "subtopic", "title": "Lawyers and courtroom workgroups", "children": [{"id": "4d90167b-e504-44f4-884f-4832189b5791", "type": "concept", "title": "Prosecutors"}, {"id": "edfa03d7-98a3-46b3-9607-86f1c4388ef0", "type": "concept", "title": "Defense attorneys"}, {"id": "3b611541-1f7f-47a3-bf1c-576ce884cc80", "type": "concept", "title": "Court clerks"}, {"id": "188d492e-8d7c-49d9-81a4-31331f648a99", "type": "concept", "title": "Probation and pretrial services"}], "description": "Repeat players shape how cases actually move through court."}, {"id": "5a190779-85fb-45ce-b064-760cda9ae1c0", "type": "subtopic", "title": "Juries, witnesses, and lay participation", "children": [{"id": "0ffbba10-7f67-4c1b-9c8b-547b203bc0ea", "type": "concept", "title": "Jury service"}, {"id": "0d2f3f1a-0d44-435f-8307-3a3088444d08", "type": "concept", "title": "Witness testimony"}, {"id": "1f9c0c87-d355-4820-995e-9717b920690c", "type": "concept", "title": "Victim participation"}, {"id": "fb413682-7e0b-4d42-9034-fbd18c85e7db", "type": "concept", "title": "Public access"}], "description": "Adjudication depends on citizens and community members as factfinders and sources of evidence."}]}, {"id": "020f7b05-aaa0-43ef-a1b2-cb9166d5ba35", "type": "topic", "title": "Prosecutorial Discretion and Charging", "description": "Analyze how prosecutors screen cases, choose charges, negotiate pleas, and influence outcomes.", "children": [{"id": "eda29e7c-c7dd-4b0a-829c-1da1f331c6b7", "type": "subtopic", "title": "Screening and charging decisions", "children": [{"id": "e1c3ab14-f3c1-4d4d-8da2-20b6f6d6372e", "type": "concept", "title": "Case screening"}, {"id": "ec20f897-f224-41b7-a086-2727b6ff3313", "type": "concept", "title": "Charge selection"}, {"id": "224820b6-7127-4776-ac84-984dcead64ea", "type": "concept", "title": "Enhancements"}, {"id": "5e44fdc1-1bfa-4fb4-b502-44f85d931aef", "type": "concept", "title": "Declination and diversion"}], "description": "Charging is one of the most consequential discretionary decisions in the criminal process."}, {"id": "6f7a7d7a-97e5-44d8-90d3-3f84b110c77f", "type": "subtopic", "title": "Ethics and minister of justice role", "children": [{"id": "334252bd-a1e9-4c01-9bc5-489b6319948b", "type": "concept", "title": "Brady obligations"}, {"id": "8ed103c4-75f6-4b70-9d83-f9e55462c87d", "type": "concept", "title": "Discovery ethics"}, {"id": "f12946c7-45d2-4675-a86b-8a8702c17efe", "type": "concept", "title": "Victim consultation"}, {"id": "ca60a35a-2594-4e1b-bab1-fbf75f4276e6", "type": "concept", "title": "Avoiding improper pressure"}], "description": "Prosecutors are advocates but also public officials with special duties to fairness and truth."}, {"id": "0d7d321e-b469-4b5f-a2fd-d2906ec05305", "type": "subtopic", "title": "Discretion and accountability", "children": [{"id": "36d4d76c-8406-4e1b-a2ea-7111dd2f20af", "type": "concept", "title": "Office policies"}, {"id": "c015d5d4-5919-4155-9aa5-1afc91133bdc", "type": "concept", "title": "Data transparency"}, {"id": "47d84ed0-68a1-4e0a-aef4-abe74aa6da33", "type": "concept", "title": "Elected prosecutors"}, {"id": "ff997ef4-591d-4c67-bda7-456921ed9dbc", "type": "concept", "title": "Racial and geographic disparities"}], "description": "Students assess how prosecutorial power is reviewed, measured, and constrained."}]}, {"id": "b0eae564-2a35-4630-becc-dd67e78436d2", "type": "topic", "title": "Defense Counsel, Indigent Defense, and Effective Assistance", "description": "Examine the constitutional, ethical, and practical role of defense counsel, including public defense systems.", "children": [{"id": "c1f9d18d-fd2a-4c0e-bc8d-a8d9ea3994d8", "type": "subtopic", "title": "Right to counsel", "children": [{"id": "fe5f22